        $recimTexto = self::requireConditionalJustification($recim, 'Com problemas', post_string('recim_texto', 3000), 'Link com a RECIM');
        $siscomisHa = self::normalizeSiscomisState(post_string('siscomis_ha', 10, 'Não'));
        $siscomisTexto = self::requireConditionalJustification($siscomisHa, 'Sim', post_string('siscomis_texto', 4000), 'SISCOMIS inoperante');
        $ataqueRelevante = self::normalizeYesNo(post_string('ataque_relevante', 10, 'Não'));
        $ataqueRelevanteTexto = self::requireConditionalJustification($ataqueRelevante, 'Sim', post_string('ataque_relevante_texto', 3000), 'Ocorrência de ataque cibernético relevante');
        $mensagensHa = self::normalizeYesNo(post_string('mensagens_ha', 10, 'Não'));
        $mensagensTexto = self::requireConditionalJustification($mensagensHa, 'Sim', post_string('mensagens_texto', 4000, 'Não há.'), 'Principais mensagens recebidas');
        $edblManutencaoHa = self::normalizeYesNo(post_string('edbl_manutencao_ha', 10, 'Não'));
        $edblManutencaoTexto = self::requireConditionalJustification($edblManutencaoHa, 'Sim', post_string('edbl_manutencao_texto', 3000, 'Não há.'), 'Problema ou manutenção prevista no EdBL');
        $rotinaAlteracaoHa = self::normalizeYesNo(post_string('rotina_alteracao_ha', 10, 'Não'));
        $rotinaAlteracaoTexto = self::requireConditionalJustification($rotinaAlteracaoHa, 'Sim', post_string('rotina_alteracao_texto', 3000, 'Sem Alteração'), 'Alteração de rotina e disciplina');
        $acidenteHa = self::normalizeYesNo(post_string('acidente_ha', 10, 'Não'));
        $acidenteTexto = self::requireConditionalJustification($acidenteHa, 'Sim', post_string('acidente_texto', 3000, 'Não.'), 'Acidente de pessoal');
        $baixadosHa = self::normalizeYesNo(post_string('baixados_ha', 10, 'Não'));
        $baixadosTexto = self::requireConditionalJustification($baixadosHa, 'Sim', post_string('baixados_texto', 3000, 'Não.'), 'Baixados');
        $bonoPublicado = self::normalizeBonoState(post_string('bono_publicado', 10, 'Sim'));
        $bonoTexto = self::requireConditionalJustification($bonoPublicado, 'Não', post_string('bono_texto', 3000, ''), 'BONO não publicado');
        $demandaExtraHa = self::normalizeYesNo(post_string('demanda_extra_ha', 10, 'Não'));
        $demandaExtraTexto = self::requireConditionalJustification($demandaExtraHa, 'Sim', post_string('demanda_extra_texto', 3000, 'Não há.'), 'Demanda extra');
        $outraAlteracaoHa = self::normalizeYesNo(post_string('outra_alteracao_ha', 10, 'Não'));
        $outraAlteracaoTexto = self::requireConditionalJustification($outraAlteracaoHa, 'Sim', post_string('outra_alteracao_texto', 3000, 'Não há.'), 'Outra alteração no serviço');
        $assinaturaNome = self::requireText(post_upper_string('assinatura_nome', 120, ''), 'Nome da assinatura');
        $assinaturaPostoRank = post_upper_string('assinatura_posto_rank', 20, '');
        $assinaturaEspecialidade = post_upper_string('assinatura_especialidade', 40, '');
        $assinaturaPosto = post_upper_string('assinatura_posto', 120, '');
        if ($assinaturaPosto === '' && ($assinaturaPostoRank !== '' || $assinaturaEspecialidade !== '')) {
            $assinaturaPosto = trim($assinaturaPostoRank . ($assinaturaEspecialidade !== '' ? ' (' . $assinaturaEspecialidade . ')' : ''));
        }
        self::requirePostoEspecialidade($assinaturaPosto, $assinaturaPostoRank, $assinaturaEspecialidade);
        $assinaturaFuncao = self::requireText(post_upper_string('assinatura_funcao', 160, ''), 'Função da assinatura');
        $atrasos = self::requireNonNegativeInteger(post_string('atrasos', 6, ''), 'Atrasos');
        $faltas = self::requireNonNegativeInteger(post_string('faltas', 6, ''), 'Faltas');

        return [
            'data_label' => $dataLabel,
            'iso_date' => $iso,
            'alerta' => strtoupper(post_string('alerta', 20, 'AZUL')),
            'alerta_descricao' => post_string('alerta_descricao', 300, 'PROBABILIDADE DE AMEAÇAS'),
            'alerta_fonte' => post_string('alerta_fonte', 120, ''),
            'alerta_extraido_em' => post_string('alerta_extraido_em', 40, date('c')),
            'ataque_relevante' => $ataqueRelevante,
            'ataque_relevante_texto' => $ataqueRelevanteTexto,
            'servicos' => $servicos,
            'servicos_sites' => self::composeServicos($servicos),
            'energia' => $energia,
            'energia_texto' => $energiaTexto,
            'chm' => $chm,
            'chm_texto' => $chmTexto,
            'recim' => $recim,
            'recim_texto' => $recimTexto,
            'siscomis_ha' => $siscomisHa,
            'siscomis_texto' => $siscomisTexto,
            'conectividade' => $conectividade,
            'om_sem_conectividade' => self::composeConectividade($conectividade),
            'siscomis_inoperante' => $siscomisHa === 'Sim' ? $siscomisTexto : 'Não.',
            'navios' => $navios,
            'navios_siscomis' => self::composeNaviosSummary($navios),
            'navios_siscomis_detalhe' => self::composeNaviosDetails($navios),
            'mensagens_ha' => $mensagensHa,
            'mensagens_texto' => $mensagensTexto,
            'agenda' => $agenda,
            'edbl_manutencao_ha' => $edblManutencaoHa,
            'edbl_manutencao_texto' => $edblManutencaoTexto,
            'rotina_alteracao_ha' => $rotinaAlteracaoHa,
            'rotina_alteracao_texto' => $rotinaAlteracaoTexto,
            'atrasos' => $atrasos,
            'faltas' => $faltas,
            'acidente_ha' => $acidenteHa,
            'acidente_texto' => $acidenteTexto,
            'baixados_ha' => $baixadosHa,
            'baixados_texto' => $baixadosTexto,
            'inspecao_om' => post_string('inspecao_om', 3000, 'Mantidas as observações do serviço anterior.'),
            'bono_publicado' => $bonoPublicado,
            'bono_texto' => $bonoTexto,
            'demanda_extra_ha' => $demandaExtraHa,
            'demanda_extra_texto' => $demandaExtraTexto,
            'outra_alteracao_ha' => $outraAlteracaoHa,
            'outra_alteracao_texto' => $outraAlteracaoTexto,
            'oficiais' => $oficiais,
            'pracas' => $pracas,
            'assinatura_nome' => $assinaturaNome,
            'assinatura_posto' => $assinaturaPosto,
            'assinatura_funcao' => $assinaturaFuncao,
            'created_at' => date('c'),
        ];
    }

    private static function normalizeIsoDate(string $value): ?string
    {
        return preg_match('/^\d{4}-\d{2}-\d{2}$/', $value) ? $value : null;
    }

    private static function normalizeEnergyState(string $value): string
    {
        return in_array($value, ['Falha', 'Instável', 'Instavel'], true) ? 'Falha' : 'OK';
    }

    private static function normalizeChmState(string $value): string
    {
        return $value === 'Sim' ? 'Sim' : 'Não';
    }

    private static function normalizeRecimState(string $value): string
    {
        return in_array($value, ['Com problemas', 'Falha', 'Instável', 'Instavel'], true) ? 'Com problemas' : 'OK';
    }

    private static function normalizeSiscomisState(string $value): string

