/**
 * Extrai tabelas e campos estruturados de documentos DOCX do Plano do Dia.
 *
 * @author CC (EN) HONORATO DCTIM
 */
final class PlanoDiaDocxExtractor
{
    private const W_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';

    /**
     * Extrai todos os dados relevantes do DOCX.
     *
     * @return array<string,mixed>
     */
    public function extract(string $docxPath): array
    {
        if (!is_file($docxPath) || !is_readable($docxPath)) {
            throw new RuntimeException('Arquivo DOCX não encontrado ou sem permissão de leitura: ' . $docxPath);
        }
        if (!class_exists(ZipArchive::class)) {
            throw new RuntimeException('Extensão php-zip/ZipArchive não está habilitada.');
        }

        $tables = $this->extractTables($docxPath);

        $data = [
            'source_file' => basename($docxPath),
            'tables_count' => count($tables),
            'oficiais' => [],
            'pracas' => [],
            'agenda' => [],
            'servico_diario' => [],
            'rotina_diaria' => [],
        ];

        $this->extractHeaderData($tables, $data);
        $this->extractServicoDiario($tables, $data);
        $this->extractRotinaDiaria($tables, $data);
        $this->extractAusencias($tables, $data);
        $this->extractReunioesFainas($tables, $data);

        return $data;
    }

    /** @return array<int, array<int, array<int, string>>> */
    /**
     * Extrai as tabelas do document.xml preservando o texto das células.
     *
     * @return list<list<list<string>>>
     */
    public function extractTables(string $docxPath): array
    {
        $zip = new ZipArchive();
        if ($zip->open($docxPath) !== true) {
            throw new RuntimeException('Não foi possível abrir o DOCX como ZIP.');
        }

        $xml = $zip->getFromName('word/document.xml');
        $zip->close();

        if (!is_string($xml) || trim($xml) === '') {
            throw new RuntimeException('word/document.xml não encontrado no DOCX.');
        }

        $dom = new DOMDocument();
        $previous = libxml_use_internal_errors(true);
        $loaded = $dom->loadXML($xml, LIBXML_NONET | LIBXML_NOERROR | LIBXML_NOWARNING);
        libxml_clear_errors();
        libxml_use_internal_errors($previous);

        if (!$loaded) {
            throw new RuntimeException('Não foi possível interpretar word/document.xml.');
        }

        $xpath = new DOMXPath($dom);
        $xpath->registerNamespace('w', self::W_NS);

        $result = [];
        foreach ($xpath->query('//w:tbl') as $tbl) {
            if (!$tbl instanceof DOMElement) {
                continue;
            }

            $rows = [];
            foreach ($xpath->query('./w:tr', $tbl) as $tr) {
                if (!$tr instanceof DOMElement) {
                    continue;
                }

                $row = [];
                foreach ($xpath->query('./w:tc', $tr) as $tc) {
                    if ($tc instanceof DOMElement) {
                        $row[] = $this->cellText($tc, $xpath);
                    }
                }

                if ($this->rowHasContent($row)) {
                    $rows[] = $row;
                }
            }

            if ($rows !== []) {
                $result[] = $rows;
            }
        }

        return $result;
    }

    private function cellText(DOMElement $tc, DOMXPath $xpath): string
    {
        $paragraphs = [];
        foreach ($xpath->query('.//w:p', $tc) as $p) {
            if (!$p instanceof DOMElement) {
                continue;
            }

            $parts = [];
            foreach ($xpath->query('.//w:t|.//w:tab|.//w:br', $p) as $node) {
                if (!$node instanceof DOMElement) {
                    continue;
                }

                if ($node->localName === 't') {
                    $parts[] = $node->textContent;
                } elseif ($node->localName === 'tab') {
                    $parts[] = ' ';
                } elseif ($node->localName === 'br') {
                    $parts[] = "\n";
                }
            }

            $text = $this->clean(implode('', $parts));
            if ($text !== '') {
                $paragraphs[] = $text;
            }
        }

        return $this->clean(implode(' ', $paragraphs));
    }

    private function extractHeaderData(array $tables, array &$data): void
    {
        foreach ($tables as $table) {
            foreach ($table as $row) {
                if (count($row) >= 2 && $this->eq($row[0], 'Dia')) {
                    $data['data_label'] = $this->extractDateLabel($row[1]);
                    $data['service_date'] = $this->labelToIsoDate((string)$data['data_label']);
                }
                if (count($row) >= 2 && $this->eq($row[0], 'Rotina')) {
                    $data['rotina_pd'] = $row[1];
                    $data['rotina_alteracao_ha'] = $this->contains($row[1], 'Normal') ? 'Não' : 'Sim';
                }
            }
        }
    }

    private function extractServicoDiario(array $tables, array &$data): void
    {
        foreach ($tables as $table) {
            if (!$this->tableContains($table, 'SERVIÇO DIÁRIO / ESTADO')) {
                continue;
            }

            foreach ($table as $row) {
                if (count($row) >= 3 && !$this->contains($row[0], 'SERVIÇO') && !$this->eq($row[1], 'Titular')) {
                    $data['servico_diario'][] = [
                        'funcao' => $row[0],
                        'titular' => $row[1],
                        'retem' => $row[2],
                    ];
                }
            }
            return;
        }
    }

    private function extractRotinaDiaria(array $tables, array &$data): void
    {
        foreach ($tables as $table) {
            $header = $table[0] ?? [];
            if (!$this->headersMatch($header, ['ROTINA NORMAL', 'ORDEM A EXECUTAR'])) {
                continue;
            }

            foreach (array_slice($table, 1) as $row) {
                if (count($row) >= 2) {
                    $data['rotina_diaria'][] = [
                        'horario' => $row[0],
                        'ordem' => $row[1],
                    ];
                }
            }
            return;
        }
    }

    private function extractAusencias(array $tables, array &$data): void
    {
        $absenceTables = [];
        foreach ($tables as $table) {
            $header = $table[0] ?? [];
            if ($this->headersMatch($header, ['TITULAR', 'MOTIVO', 'PERÍODO', 'SUBSTITUTO(S)'])) {
                $absenceTables[] = $table;
            }
        }

        if (isset($absenceTables[0])) {
            $data['oficiais'] = $this->parsePessoaRows($absenceTables[0]);
        }
        if (isset($absenceTables[1])) {
            $data['pracas'] = $this->parsePessoaRows($absenceTables[1]);
        }
    }

    private function extractReunioesFainas(array $tables, array &$data): void
    {
        foreach ($tables as $table) {
            $header = $table[0] ?? [];
            if (!$this->headersMatch($header, ['EVENTO', 'DATA HORA', 'LOCAL', 'PARTICIPANTES', 'RESPONSÁVEL', 'ASSUNTO'])) {
                continue;
            }

            foreach (array_slice($table, 1) as $row) {
                if (!$this->rowHasMeaningfulContent($row) || $this->isReunioesFainasLabelRow($row)) {
                    continue;
                }

                $evento = $row[0] ?? '';
                $dataHora = $row[1] ?? '';
                $local = $row[2] ?? '';
                $participantes = $row[3] ?? '';
                $responsavel = $row[4] ?? '';
                $assunto = $row[5] ?? '';

                $atividade = $evento;
                if ($assunto !== '') {
                    $atividade .= ' — ' . $assunto;
                }
                if (!$this->hasMeaningfulText([$dataHora, $atividade, $participantes, $responsavel])) {
                    continue;
                }

                $data['agenda'][] = [
                    'local' => $local,
                    'horario' => $dataHora,
                    'atividade' => $atividade,
                    'evento' => $evento,
                    'participantes' => $participantes,
                    'responsavel' => $responsavel,
                    'assunto' => $assunto,
                ];
            }
            return;
        }
    }

