declare(strict_types=1);

/**
 * Parser textual legado para dados extraídos do Plano do Dia.
 *
 * @author CC (EN) HONORATO DCTIM
 */
final class PlanoDiaParser
{
    /**
     * Parser leve para texto extraído do Plano do Dia.
     * Nesta baseline não executa binários nem aceita caminho arbitrário do usuário.
     *
     * @return array{oficiais:array<int,array<string,string>>,pracas:array<int,array<string,string>>}
     */
    public static function extractAbsencesFromText(string $text): array
    {
        $text = preg_replace('/\r\n?|\n/u', "\n", $text);
        $officers = self::section($text, '2.5.', '2.6.');
        $ratings = self::section($text, '2.6.', '2.7.');

        return [
            'oficiais' => self::absenceRows($officers),
            'pracas' => self::absenceRows($ratings),
        ];
    }

    /**
     * Extrai reuniões/fainas internas do item 2.7 do Plano do Dia.
     *
     * @return list<array<string,string>>
     */
    public static function extractFainasFromText(string $text): array
    {
        $section = self::section($text, '2.7.', '2.8.');
        return self::meetingRows($section);
    }

    /**
     * Extrai campos usados diretamente para pré-preencher o formulário.
     *
     * @return array<string,mixed>
     */
    public static function extractFormDataFromText(string $text): array
    {
        $text = preg_replace('/\r\n?|\n/u', "\n", $text);
        $absences = self::extractAbsencesFromText($text);
        $serviceDate = self::extractServiceDate($text);

        $data = [
            'oficiais' => $absences['oficiais'],
            'pracas' => $absences['pracas'],
        ];

        if ($serviceDate !== null) {
            $data['service_date'] = $serviceDate;
            $data['data_label'] = iso_to_label_date($serviceDate) ?? '';
        }

        return $data;
    }

    private static function section(string $text, string $start, string $end): string
    {
        if (!preg_match('/^\s*' . preg_quote($start, '/') . '/mu', $text, $startMatch, PREG_OFFSET_CAPTURE)) {
            return '';
        }

        $ini = (int)$startMatch[0][1];
        $fim = null;

        if ($end !== '' && preg_match('/^\s*' . preg_quote($end, '/') . '/mu', $text, $endMatch, PREG_OFFSET_CAPTURE, $ini + strlen($start))) {
            $fim = (int)$endMatch[0][1];
        }

        if ($fim === null) {
            $fim = strlen($text);
        }

        return trim(substr($text, $ini, $fim - $ini));
    }

    private static function absenceRows(string $section): array
    {
        $section = preg_replace('/\x{200B}|\x{200D}|\x{FEFF}/u', '', $section);
        $lines = preg_split('/\n+/u', $section) ?: [];
        $fragments = [];
        foreach ($lines as $line) {
            if (preg_match('/AUS[ÊE]NCIA|TITULAR|MOTIVO|PER[ÍI]ODO|SUBSTITUTO/u', $line)) {
                continue;
            }
            $line = trim((string)$line);
            if ($line === '') {
                continue;
            }

            $parts = preg_split('/\s{2,}/u', $line) ?: [];
            $parts = array_values(array_filter(array_map(static fn(string $value): string => trim($value), $parts), static fn(string $value): bool => $value !== ''));
            if ($parts === []) {
                continue;
            }

            $titular = '';
            $motivo = '';
            $periodo = '';
            $substituto = '';

            if (count($parts) >= 4) {
                [$titular, $motivo, $periodo, $substituto] = array_pad(array_slice($parts, 0, 4), 4, '');
            } elseif (count($parts) === 3) {
                if (self::looksLikePerson($parts[0])) {
                    [$titular, $motivo, $periodo] = $parts;
                } else {
                    [$motivo, $periodo, $substituto] = $parts;
                }
            } elseif (count($parts) === 2) {
                if (self::looksLikePerson($parts[0])) {
                    [$titular, $substituto] = $parts;
                } else {
                    [$motivo, $periodo] = $parts;
                }
            } else {
                $motivo = $parts[0];
            }

            if ($titular === '' && $motivo === '' && $periodo === '' && $substituto === '') {
                continue;
            }

            $fragments[] = compact('titular', 'motivo', 'periodo', 'substituto');
        }

        return self::collapseAbsenceFragments($fragments);
