                    'periodo' => clean_line($m['periodo'], 200),
                    'substituto' => clean_line($m['substituto'], 200),
                ];
            }
        }
        return $rows;
    }

    private static function collapseAbsenceFragments(array $fragments): array
    {
        $rows = [];
        $cluster = [];

        $flush = static function (array $parts) use (&$rows): void {
            if ($parts === []) {
                return;
            }

            $titular = '';
            $substituto = '';
            $motivos = [];
            $periodos = [];

            foreach ($parts as $part) {
                if ($titular === '' && ($part['titular'] ?? '') !== '') {
                    $titular = (string)$part['titular'];
                }
                if ($substituto === '' && ($part['substituto'] ?? '') !== '') {
                    $substituto = (string)$part['substituto'];
                }
                if (($part['motivo'] ?? '') !== '') {
                    $motivos[] = (string)$part['motivo'];
                }
                if (($part['periodo'] ?? '') !== '') {
                    $periodos[] = (string)$part['periodo'];
                }
            }

            if ($titular === '' && $motivos === [] && $periodos === [] && $substituto === '') {
                return;
            }

            $rows[] = [
                'titular' => clean_line($titular, 200),
                'motivo' => clean_line(implode(' / ', array_values(array_unique($motivos))), 200),
                'periodo' => clean_line(implode(' / ', array_values(array_unique($periodos))), 200),
                'substituto' => clean_line($substituto, 200),
            ];
        };

        foreach ($fragments as $fragment) {
            $isComplete = ($fragment['titular'] ?? '') !== '' && ((($fragment['motivo'] ?? '') !== '') || (($fragment['periodo'] ?? '') !== ''));

            if ($isComplete) {
                $flush($cluster);
                $cluster = [];
                $flush([$fragment]);
                continue;
            }

            $cluster[] = $fragment;
        }

        $flush($cluster);

        return array_values(array_filter($rows, static fn(array $row): bool => implode('', $row) !== ''));
    }

