    private function parsePessoaRows(array $table): array
    {
        $rows = [];
        foreach (array_slice($table, 1) as $row) {
            $row = array_pad($row, 4, '');
            $titular = $this->clean($row[0]);
            $motivo = $this->clean($row[1]);
            $periodo = $this->clean($row[2]);
            $substituto = $this->clean($row[3]);

            if (!$this->hasMeaningfulText([$titular, $motivo, $periodo, $substituto])) {
                continue;
            }
            if ($this->isFooterOrContinuationRow([$titular, $motivo, $periodo, $substituto])) {
                continue;
            }

            $rows[] = [
                'titular' => $titular,
                'motivo' => $motivo,
                'periodo' => $periodo,
                'substituto' => $substituto,
            ];
        }
        return $rows;
    }

    private function isFooterOrContinuationRow(array $row): bool
    {
        $joined = $this->norm(implode(' ', array_map(static fn($value): string => (string)$value, $row)));
        $joined = preg_replace('/[\s\-\—\–\_\.\/]+/u', ' ', $joined) ?? $joined;
        $joined = trim($joined);

        if (preg_match('/\bCONTINUACAO DO PLANO DO DIA\b/u', $joined) === 1) {
            return true;
        }
        if (preg_match('/^\d+\s+DE\s+\d+$/u', $joined) === 1) {
            return true;
        }
        if (preg_match('/^\d+\s+DE\s+\d+\s+CONTINUACAO DO PLANO DO DIA\b/u', $joined) === 1) {
            return true;
        }

        return false;
    }

