    private function labelToIsoDate(string $label): string
    {
        if (!preg_match('/^(\d{2})([A-Z]{3})(\d{4})$/u', mb_strtoupper($label, 'UTF-8'), $m)) {
            return '';
        }

        $months = [
            'JAN' => '01', 'FEV' => '02', 'MAR' => '03', 'ABR' => '04',
            'MAI' => '05', 'JUN' => '06', 'JUL' => '07', 'AGO' => '08',
            'SET' => '09', 'OUT' => '10', 'NOV' => '11', 'DEZ' => '12',
        ];

        $month = $months[$m[2]] ?? null;
        if ($month === null) {
            return '';
        }

        return $m[3] . '-' . $month . '-' . $m[1];
    }

