function storage_path(string $path = ''): string
{
    $base = app_root() . DIRECTORY_SEPARATOR . 'storage';
    return $path === '' ? $base : $base . DIRECTORY_SEPARATOR . ltrim($path, DIRECTORY_SEPARATOR);
}

/**
