    private function absoluteUrl(string $baseUrl, string $href): string
    {
        if (preg_match('~^https?://~i', $href)) {
            return $href;
        }

        $baseUrl = rtrim($baseUrl, '/');

        if (str_starts_with($href, '/')) {
            return $baseUrl . $href;
        }

        return $baseUrl . '/' . ltrim($href, '/');
    }

    private function importPlanoDiaPdfUrl(string $pdfUrl, string $serviceDate, array $context = []): array
    {
        return $this->importRemotePdf($pdfUrl, $serviceDate, $context);
    }

    private function importRemotePdf(string $pdfUrl, string $serviceDate, array $context = []): array
    {
        $targetDir = storage_path('sources/plano-dia');

        if (!is_dir($targetDir) && !mkdir($targetDir, 0770, true) && !is_dir($targetDir)) {
            throw new RuntimeException("Não foi possível preparar a pasta {$targetDir}");
        }

        $label = iso_to_label_date($serviceDate) ?? str_replace('-', '', $serviceDate);
        $storedName = 'pd' . strtolower($label) . '.pdf';
        $targetPath = $targetDir . DIRECTORY_SEPARATOR . $storedName;

        $pdfContent = $this->httpGet($pdfUrl);

        if (!str_starts_with($pdfContent, '%PDF')) {
            throw new RuntimeException(
                "O arquivo baixado não parece ser PDF. URL: {$pdfUrl}. Destino: {$targetPath}"
            );
        }

        if (is_file($targetPath) && !unlink($targetPath)) {
            throw new RuntimeException("Não foi possível sobrescrever o PDF existente: {$targetPath}");
        }

        if (file_put_contents($targetPath, $pdfContent) === false) {
            throw new RuntimeException("Não foi possível salvar o PDF em: {$targetPath}");
        }

        $this->convertPdfToDocx($targetPath);

        $data = [
            'evidence_file_original_name' => basename(parse_url($pdfUrl, PHP_URL_PATH) ?: $storedName),
            'evidence_file_stored_name' => $storedName,
            'evidence_file_extension' => 'pdf',
            'evidence_file_imported_at' => date('c'),
            'service_date' => $serviceDate,
            'data_label' => $label,
            'evidence_remote_url' => $pdfUrl,
            'plano_dia_pdf_url' => $pdfUrl,
            'plano_dia_node_url' => $context['node_url'] ?? '',
            'plano_dia_calendar_url' => $context['calendar_url'] ?? '',
            'plano_dia_local_path' => $targetPath,
            'plano_dia_docx_local_path' => preg_replace('/\.pdf$/i', '.docx', $targetPath) ?: '',
        ];

        $importedFormData = $this->extractStructuredData($targetPath, 'pdf');
        $docxFormData = $this->extractPlanoDiaDocxFormData($targetPath);
        if ($docxFormData !== []) {
            $importedFormData = array_replace_recursive($importedFormData, $docxFormData);
        }

        if ($importedFormData) {
            $data['imported_form_data'] = $importedFormData;

            if (!empty($importedFormData['service_date'])) {
                $data['service_date'] = $importedFormData['service_date'];
            }

            if (!empty($importedFormData['data_label'])) {
                $data['data_label'] = $importedFormData['data_label'];
            }
        }

